def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def best_toward(start, targets, prefer_max=False):
        sx, sy = start
        cand = []
        for t in targets or []:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = abs(tx - sx) + abs(ty - sy)
            cand.append((d, tx, ty))
        if not cand:
            return None
        if prefer_max:
            _, tx, ty = max(cand)
        else:
            _, tx, ty = min(cand)
        return clamp_step(tx - sx), clamp_step(ty - sy)

    env = observation.get("environment_name", "") or ""
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [clamp_step(ox - sx), clamp_step(oy - sy)]
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        target = best_toward((ox, oy), corners, prefer_max=True)
        if target is None:
            return [0, 0]
        dx, dy = target
        return [dx, dy]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        move = best_toward((sx, sy), targets, prefer_max=False)
        if move is not None:
            return [move[0], move[1]]
        # fallback: move toward opponent, else explore by center bias
        if ox != sx or oy != sy:
            return [clamp_step(ox - sx), clamp_step(oy - sy)]
        cx = (w - 1) // 2 if w else sx
        cy = (h - 1) // 2 if h else sy
        return [clamp_step(cx - sx), clamp_step(cy - sy)]

    resources = observation.get("resources") or observation.get("resource_cells") or []
    move = best_toward((sx, sy), resources, prefer_max=False)
    if move is not None:
        return [move[0], move[1]]

    # Generic fallback: seek nearest interesting object, otherwise drift toward opponent
    extras = observation.get("objects") or observation.get("items") or []
    move = best_toward((sx, sy), extras, prefer_max=False)
    if move is not None:
        return [move[0], move[1]]

    return [clamp_step(ox - sx), clamp_step(oy - sy)]

